package lk.gov.health.govcare.media;
import lk.gov.health.govcare.security.*;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.util.*;
@RestController @RequestMapping("/api/media") public class MediaController{private final MediaService s;private final CurrentUser c;public MediaController(MediaService s,CurrentUser c){this.s=s;this.c=c;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@PreAuthorize("hasAuthority('MEDIA_UPLOAD')")public Map<String,Object> upload(@RequestParam MultipartFile file,@RequestParam(required=false)UUID patientId,@RequestParam String module,@RequestParam(defaultValue="private")String visibilityLevel)throws IOException{return s.store(c.get(),file,patientId,module,visibilityLevel);}@GetMapping @PreAuthorize("hasAuthority('MEDIA_VIEW')")public List<Map<String,Object>>list(@RequestParam(required=false)UUID patientId){return s.list(c.get(),patientId);}@GetMapping("/{id}/download")@PreAuthorize("hasAuthority('MEDIA_VIEW')")public ResponseEntity<Resource>download(@PathVariable UUID id)throws IOException{Map<String,Object>m=s.get(c.get(),id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(Objects.toString(m.get("mimeType"),MediaType.APPLICATION_OCTET_STREAM_VALUE))).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(Objects.toString(m.get("originalFileName"),"download.bin")).build().toString()).body(s.resource(c.get(),id));}@PatchMapping("/{id}/release")@PreAuthorize("hasAnyAuthority('PATIENT_UPDATE_DEMOGRAPHICS','CONSULTATION_UPDATE','USER_MANAGE')")public Map<String,Object>release(@PathVariable UUID id){return s.release(c.get(),id);}}
